import {describe,it,expect} from 'vitest';import {MaterialLedger} from '../src/game/material-ledger.js';
describe('MaterialLedger',()=>{it('adds and never consumes below zero',()=>{const l=new MaterialLedger({sand:10,cement:0,water:0,concrete:0});expect(l.add('sand',5)).toBe(15);expect(l.consume('sand',16)).toBe(false);expect(l.stock.sand).toBe(15)});it('mixes ideal concrete',()=>{const l=new MaterialLedger();const b=l.mixConcrete({sand:200,cement:100,water:50});expect(b).toEqual({volume:350,strength:1,cureSeconds:22});expect(l.stock.concrete).toBe(350)});it('penalizes a bad ratio',()=>{const l=new MaterialLedger();expect(l.mixConcrete({sand:300,cement:100,water:100}).strength).toBeLessThan(1)})});
